/* UE 2 — Droit des affaires (programme réformé, session 2027) */
(function () {
  var C = window.DCG_CARDS, Q = window.DCG_QCM;

  C.push(
    // ---------- Contexte juridique ----------
    { id: 'ue2-101', ue: 2, q: "Quelles sont les sources du droit des affaires ?", a: "La loi (Code de commerce, Code civil, Code monétaire et financier, Code pénal...), le règlement, la jurisprudence, les usages et la doctrine. Le droit de l'Union européenne (règlements d'application directe, directives à transposer) s'y ajoute." },
    { id: 'ue2-102', ue: 2, q: "Qui est commerçant ?", a: "Celui qui exerce des actes de commerce et en fait sa profession habituelle (art. L121-1 C. com.). Il est tenu de s'immatriculer au RCS, de tenir une comptabilité, etc. Les actes de commerce sont des actes de commerce par nature (achat pour revendre...), par la forme (lettre de change, société commerciale par la forme) ou par accessoire." },
    { id: 'ue2-103', ue: 2, q: "Quel est le statut actuel de l'entrepreneur individuel (EI) ?", a: "Depuis la loi n° 2022-172 du 14 février 2022 (applicable depuis le 15 mai 2022), tout entrepreneur individuel dispose d'un patrimoine professionnel séparé de son patrimoine personnel : ses créanciers professionnels ne peuvent en principe saisir que le patrimoine professionnel. L'EIRL n'est plus créée depuis cette date.", d: "Loi du 14/02/2022, applicable depuis le 15/05/2022" },
    { id: 'ue2-104', ue: 2, q: "Quels critères pour choisir la forme juridique d'une entreprise ?", a: "Responsabilité des associés, nombre d'associés, capital minimum, régime fiscal (IR/IS) et social du dirigeant, pouvoirs du dirigeant, liberté statutaire, facilité de transmission des titres et d'accueil d'investisseurs, coût et formalisme de fonctionnement." },
    { id: 'ue2-105', ue: 2, q: "Définition de la société (art. 1832 du Code civil) ?", a: "Contrat par lequel deux ou plusieurs personnes (ou une seule, dans les cas prévus par la loi) conviennent d'affecter à une entreprise commune des biens ou leur industrie en vue de partager le bénéfice ou de profiter de l'économie qui pourra en résulter. Les associés s'engagent à contribuer aux pertes." },
    { id: 'ue2-04', ue: 2, q: "Quelles sont les conditions de fond propres au contrat de société ?", a: "Pluralité d'associés (sauf société unipersonnelle), apports, vocation aux bénéfices et contribution aux pertes (pas de clause léonine), et affectio societatis (volonté de collaborer à l'entreprise commune sur un pied d'égalité)." },
    { id: 'ue2-106', ue: 2, q: "Quelles sont les conditions générales de validité du contrat de société ?", a: "Celles de tout contrat (art. 1128 C. civ.) : consentement des parties, capacité de contracter, contenu licite et certain. S'y ajoutent les conditions propres au contrat de société et les règles spéciales (ex. capacité commerciale pour être associé d'une SNC)." },
    { id: 'ue2-107', ue: 2, q: "Qu'est-ce qu'une clause léonine ?", a: "Une clause qui attribue à un associé la totalité du profit ou l'exonère de toute contribution aux pertes (ou exclut un associé de tout profit). Elle est réputée non écrite (art. 1844-1 C. civ.), la société restant valable." },
    { id: 'ue2-108', ue: 2, q: "Quels sont les effets de la nullité d'une société ?", a: "La nullité n'a pas d'effet rétroactif : la société est dissoute et liquidée, les actes passés restent valables (société de fait). L'action en nullité se prescrit par 3 ans à compter du jour où la nullité est encourue, et le juge peut accorder un délai de régularisation.", d: "Prescription de 3 ans (art. 1844-14 C. civ.)" },
    { id: 'ue2-109', ue: 2, q: "Quels sont les attributs de la personnalité morale ?", a: "Un nom (dénomination sociale), un siège social, un patrimoine propre distinct de celui des associés, une nationalité, la capacité de contracter et d'agir en justice. Elle naît à l'immatriculation au RCS et disparaît à la radiation après clôture de la liquidation." },
    { id: 'ue2-110', ue: 2, q: "Comment immatricule-t-on une société aujourd'hui ?", a: "Par une formalité unique déposée sur le guichet unique électronique des formalités d'entreprises (géré par l'INPI), qui transmet le dossier au greffe du RCS et aux organismes concernés. Une annonce légale (JAL) de la constitution est publiée.", d: "Guichet unique depuis le 01/01/2023" },
    { id: 'ue2-111', ue: 2, q: "Quelles mentions comportent les statuts ?", a: "Forme, durée (99 ans maximum), dénomination, siège, objet social, montant du capital et apports, répartition des titres, organisation de la direction et des décisions collectives, modalités de partage des résultats et de liquidation." },
    { id: 'ue2-112', ue: 2, q: "Que change la loi PACTE (2019) pour l'intérêt social ?", a: "La société est gérée dans son intérêt social, en prenant en considération les enjeux sociaux et environnementaux de son activité (art. 1833 C. civ.). Elle peut se doter d'une raison d'être (art. 1835), et devenir société à mission (art. L210-10 C. com.) avec objectifs, comité de mission et vérification par un organisme tiers indépendant.", d: "Loi n° 2019-486 du 22/05/2019" },
    { id: 'ue2-113', ue: 2, q: "Qu'est-ce qu'une société en formation et qui répond de ses actes ?", a: "La société entre la signature des statuts et son immatriculation n'a pas la personnalité morale. Les personnes qui ont agi en son nom en sont tenues solidairement ; après l'immatriculation, la société peut les reprendre (par mandat, état des actes annexé aux statuts ou décision des associés), avec effet rétroactif." },
    { id: 'ue2-114', ue: 2, q: "Quand une société acquiert-elle la personnalité morale ?", a: "À son immatriculation au RCS (art. 1842 C. civ.). Avant, c'est une société en formation : les actes passés pour elle engagent leurs auteurs, puis sont repris par la société après l'immatriculation." },

    // ---------- Apports, capital, associés ----------
    { id: 'ue2-06', ue: 2, q: "Quelles sont les 3 sortes d'apports ?", a: "Apports en numéraire (argent), en nature (biens en propriété ou en jouissance) et en industrie (travail, savoir-faire). Les apports en industrie ne concourent pas à la formation du capital (ils donnent droit à des parts d'industrie, notamment en SNC et SAS)." },
    { id: 'ue2-07', ue: 2, q: "Quand un commissaire aux apports est-il requis ?", a: "Pour évaluer les apports en nature : en SA, en principe toujours ; en SARL, si un apport dépasse 30 000 € ou si l'ensemble des apports en nature dépasse la moitié du capital (sauf décision unanime des associés de ne pas y recourir). Les associés restent responsables de la valeur retenue pendant 5 ans.", d: "Seuil de 30 000 € (art. L223-9 C. com.)" },
    { id: 'ue2-08', ue: 2, q: "Libération du capital à la constitution : quelle fraction minimum ?", a: "SARL : au moins 1/5 des apports en numéraire. SA et SAS : au moins la moitié. Le solde doit être libéré dans les 5 ans (pas de délai pour les apports en nature, intégralement libérés)." },
    { id: 'ue2-115', ue: 2, q: "Rôle et limites du capital social ?", a: "Le capital est la somme des apports (hors industrie) : il mesure l'engagement des associés et sert de garantie aux créanciers, mais sa fonction de gage est limitée (le capital peut être faible et il est dépensé dans l'activité). Il détermine aussi le pouvoir de chaque associé (parts/actions)." },
    { id: 'ue2-116', ue: 2, q: "Quels sont les droits des associés ?", a: "Droit de participer aux décisions collectives et de voter, droit aux dividendes, droit à l'information (documents sociaux, questions écrites), droit sur le boni de liquidation, droit de céder ses titres (sous réserve d'agrément)." },
    { id: 'ue2-117', ue: 2, q: "Quelles sont les obligations des associés ?", a: "Réaliser leur apport, contribuer aux pertes (dans la limite des apports ou indéfiniment selon la forme), agir de bonne foi dans l'intérêt social, et respecter les clauses statutaires et pactes (non-concurrence, loyauté...)." },

    // ---------- Formes sociétaires ----------
    { id: 'ue2-01', ue: 2, q: "Capital minimum d'une SA ?", a: "37 000 €. Au moins la moitié doit être libérée à la constitution." },
    { id: 'ue2-02', ue: 2, q: "Nombre minimum d'actionnaires d'une SA non cotée / cotée ?", a: "2 pour une SA non cotée, 7 pour une SA cotée." },
    { id: 'ue2-03', ue: 2, q: "Capital minimum d'une SARL et d'une SAS ?", a: "Aucun : le capital est librement fixé par les statuts (1 € possible)." },
    { id: 'ue2-09', ue: 2, q: "SNC : statut des associés et responsabilité ?", a: "Les associés sont commerçants et répondent indéfiniment et solidairement des dettes sociales, après mise en demeure infructueuse de la société. Cession de parts : agrément unanime des associés sauf clause contraire." },
    { id: 'ue2-10', ue: 2, q: "Société en commandite simple : deux catégories d'associés ?", a: "Commandités : commerçants, responsabilité indéfinie et solidaire, ils dirigent. Commanditaires : responsabilité limitée aux apports, interdiction de faire des actes de gestion externe. (La SCA ne figure plus au programme du DCG.)" },
    { id: 'ue2-29', ue: 2, q: "Société civile (ex. SCI) : régime de responsabilité ?", a: "Les associés répondent indéfiniment des dettes sociales, mais non solidairement : chacun à proportion de ses parts, après poursuite préalable infructueuse de la société (art. 1857 C. civ.)." },
    { id: 'ue2-11', ue: 2, q: "SARL : nombre d'associés et responsabilité ?", a: "De 1 (EURL) à 100 associés. Responsabilité limitée aux apports. Le gérant est une personne physique (associé ou non) ; parts sociales non négociables librement." },
    { id: 'ue2-118', ue: 2, q: "SARL : nomination, révocation et rémunération du gérant ?", a: "Nommé dans les statuts ou par décision ultérieure des associés (plus de la moitié des parts, sans quorum), généralement pour une durée fixée. Révocable par décision des associés représentant plus de la moitié des parts (indemnité si absence de juste motif) ou en justice pour cause légitime. Rémunération fixée par la collectivité des associés." },
    { id: 'ue2-12', ue: 2, q: "Pouvoirs du gérant de SARL à l'égard des tiers ?", a: "Il peut accomplir tous actes de gestion dans l'intérêt de la société (sauf limitations statutaires, inopposables aux tiers). Il engage la société même par un acte étranger à l'objet social, sauf preuve que le tiers savait ou ne pouvait ignorer que l'acte dépassait l'objet social." },
    { id: 'ue2-13', ue: 2, q: "SARL : règles de cession de parts à un tiers ?", a: "Agrément préalable de la majorité des associés représentant au moins la moitié des parts sociales (le cédant peut voter). Cessions entre associés, au conjoint, aux ascendants ou descendants : libres, sauf clause statutaire contraire. En cas de refus d'agrément : rachat des parts dans un délai de 3 mois." },
    { id: 'ue2-14', ue: 2, q: "SARL : majorités des décisions collectives ?", a: "Ordinaires : plus de la moitié des parts (à défaut, majorité des votes émis à la 2e consultation). Extraordinaires (modification des statuts) : 3/4 des parts. Unanimité : changement de nationalité, augmentation des engagements des associés. Comptes : approbation dans les 6 mois de la clôture." },
    { id: 'ue2-119', ue: 2, q: "SARL : conventions réglementées et conventions interdites ?", a: "Conventions entre la société et un gérant ou associé : rapport du gérant ou du commissaire aux comptes, puis approbation par les associés (l'intéressé ne vote pas). Interdit aux gérants et associés personnes physiques d'obtenir de la société des emprunts, découverts ou cautions (conventions interdites, art. L223-21)." },
    { id: 'ue2-120', ue: 2, q: "Gérant majoritaire ou minoritaire : quelle conséquence sociale ?", a: "Gérant majoritaire (plus de 50 % des parts, avec conjoint et enfants mineurs) : régime des travailleurs non salariés (TNS). Gérant minoritaire ou égalitaire : assimilé salarié (régime général, sans assurance chômage)." },
    { id: 'ue2-121', ue: 2, q: "EURL et SASU : particularités de l'associé unique ?", a: "Les décisions relevant des associés sont prises par l'associé unique et consignées dans un registre. Les conventions conclues avec lui sont soumises à rapport. EURL = SARL à associé unique ; SASU = SAS à associé unique (grande liberté statutaire)." },
    { id: 'ue2-15', ue: 2, q: "SA : deux modes d'organisation de la direction ?", a: "Conseil d'administration (3 à 18 membres) avec un PDG ou une dissociation président/directeur général ; ou directoire (2 à 5 membres, 7 si cotée) et conseil de surveillance (3 à 18 membres)." },
    { id: 'ue2-122', ue: 2, q: "SA à conseil d'administration : rôle du conseil, du PDG et du DG ?", a: "Le conseil détermine les orientations de l'activité et contrôle la gestion ; le PDG (président + directeur général) ou le DG représente la société et a les pouvoirs les plus étendus (limitations inopposables aux tiers). Les administrateurs sont nommés par l'AGO pour 6 ans maximum et révocables à tout moment (ad nutum)." },
    { id: 'ue2-123', ue: 2, q: "SA à directoire et conseil de surveillance : qui fait quoi ?", a: "Le directoire dirige la société (membres personnes physiques nommés par le conseil de surveillance pour 2 à 6 ans). Le conseil de surveillance contrôle en permanence la gestion, nomme et révoque les membres du directoire, et peut demander des documents. Séparation stricte entre direction et contrôle." },
    { id: 'ue2-16', ue: 2, q: "SA : quorum et majorité de l'AGO et de l'AGE ?", a: "AGO : quorum 1/5 des actions ayant le droit de vote à la 1re convocation (aucun à la 2e), majorité des voix exprimées. AGE : quorum 1/4 (1/5 à la 2e convocation), majorité des 2/3 des voix exprimées. Les voix exprimées excluent abstentions, votes blancs et nuls.", d: "Art. L225-96 et L225-98 C. com. (ord. 2020-1142, en vigueur depuis le 01/01/2021)" },
    { id: 'ue2-17', ue: 2, q: "Quelle est la compétence de l'AGO et celle de l'AGE ?", a: "AGO : approbation des comptes, affectation du résultat, nomination et révocation des administrateurs et commissaires aux comptes, conventions réglementées. AGE : modification des statuts (capital, objet, siège...), fusion, transformation, dissolution anticipée." },
    { id: 'ue2-124', ue: 2, q: "SA : droits particuliers des actionnaires ?", a: "Droit préférentiel de souscription, droit de vote double (actions nominatives détenues 2 ans, si statuts), droit de poser des questions écrites avant l'assemblée, droit de demander une expertise de gestion (5 % du capital), action en responsabilité contre les dirigeants. Actions de préférence : droits différents (ex. sans droit de vote)." },
    { id: 'ue2-125', ue: 2, q: "Quelles nouveautés apporte la loi attractivité de 2024 ?", a: "Elle permet aux sociétés qui s'introduisent en bourse d'émettre des actions à droit de vote multiple, facilite le financement des entreprises et modernise le fonctionnement des sociétés (dématérialisation accrue des assemblées et des décisions des organes sociaux).", d: "Loi n° 2024-537 du 13/06/2024" },
    { id: 'ue2-19', ue: 2, q: "SAS : caractéristiques essentielles ?", a: "Grande liberté statutaire, capital libre, nombre d'associés illimité, président obligatoire (personne physique ou morale), pas d'offre au public de titres financiers (actions). SASU : un seul associé." },
    { id: 'ue2-126', ue: 2, q: "SAS : quelles décisions doivent obligatoirement être collectives ?", a: "Les statuts fixent librement les décisions collectives, mais certaines doivent être prises par les associés : augmentation, amortissement ou réduction du capital, fusion, scission, dissolution, transformation, nomination des commissaires aux comptes, approbation des comptes et affectation des bénéfices." },
    { id: 'ue2-127', ue: 2, q: "SAS : quelles clauses statutaires spécifiques sur les titres ?", a: "Clauses d'inaliénabilité (durée limitée à 10 ans), d'agrément, de préemption, d'exclusion d'un associé, de changement de contrôle, de sortie conjointe : elles permettent de contrôler l'actionnariat. Elles doivent être adoptées dans les conditions prévues par les statuts (souvent l'unanimité)." },
    { id: 'ue2-20', ue: 2, q: "Quelle est la procédure des conventions réglementées en SA ?", a: "Autorisation préalable du conseil (l'intéressé ne vote pas), rapport spécial du commissaire aux comptes, puis approbation par l'AG ordinaire (l'intéressé ne vote pas). Les conventions courantes conclues à des conditions normales échappent à la procédure ; certaines conventions sont interdites (emprunts des administrateurs personnes physiques)." },
    { id: 'ue2-18', ue: 2, q: "Quand un commissaire aux comptes est-il obligatoire et pour quelle durée ?", a: "Obligatoire en SA et SCA, et en SARL, SAS, SNC, SCS dès que deux des trois seuils suivants sont dépassés (sur 2 exercices consécutifs) : 5 M€ de total de bilan, 10 M€ de chiffre d'affaires HT, 50 salariés. Mandat de 6 exercices.", d: "Seuils relevés par le décret n° 2024-152 du 28/02/2024 (exercices ouverts depuis le 01/01/2024) ; avant : 4 M€ / 8 M€ / 50" },
    { id: 'ue2-128', ue: 2, q: "Quels seuils de commissaire aux comptes pour les sociétés d'un groupe ?", a: "Une société qui contrôle ou est contrôlée par une société tenue de nommer un commissaire aux comptes en nomme un dès que deux des trois seuils suivants sont dépassés : 2,5 M€ de total de bilan, 5 M€ de chiffre d'affaires HT, 25 salariés.", d: "Seuils 2024 issus de sources secondaires — à confirmer avec ton cours" },

    // ---------- Résultats et dividendes ----------
    { id: 'ue2-21', ue: 2, q: "Réserve légale : règle de dotation ?", a: "On prélève 5 % du bénéfice de l'exercice (diminué des pertes antérieures) jusqu'à ce que la réserve atteigne 10 % du capital (SA, SARL, SAS selon statuts)." },
    { id: 'ue2-22', ue: 2, q: "Bénéfice distribuable ?", a: "Bénéfice de l'exercice − pertes antérieures − dotation à la réserve légale + report à nouveau bénéficiaire (+ réserves disponibles). Aucune distribution si les capitaux propres deviendraient inférieurs au capital augmenté des réserves non distribuables. Les dividendes fictifs sont un délit." },
    { id: 'ue2-129', ue: 2, q: "Quelles sont les règles de paiement des dividendes ?", a: "Les modalités sont fixées par l'assemblée ou, à défaut, par le dirigeant ; le paiement intervient dans les 9 mois de la clôture sauf prolongation par justice. Possibilité d'acomptes sur dividendes avec bilan certifié par un CAC. Les dividendes irrégulièrement perçus doivent être restitués (3 ans)." },
    { id: 'ue2-23', ue: 2, q: "Capitaux propres inférieurs à la moitié du capital : que faire ?", a: "Le dirigeant convoque les associés dans les 4 mois de l'approbation des comptes pour décider de la dissolution anticipée. Si elle est rejetée, la société doit régulariser au plus tard à la clôture du 2e exercice suivant (en reconstituant les capitaux propres ou en réduisant le capital)." },

    // ---------- Vie de la société : capital, transformation, disparition ----------
    { id: 'ue2-24', ue: 2, q: "Quels sont les modes d'augmentation de capital ?", a: "Apports nouveaux (numéraire ou nature), incorporation de réserves, bénéfices ou primes (élévation de la valeur nominale ou attribution gratuite), compensation de créances, conversion d'obligations. Décidée par l'AGE (ou par le dirigeant sur délégation) ; en SA, droit préférentiel de souscription." },
    { id: 'ue2-130', ue: 2, q: "Qu'est-ce que le droit préférentiel de souscription ?", a: "En cas d'augmentation de capital en numéraire, chaque actionnaire a, proportionnellement à sa part, un droit de souscrire par priorité les titres nouveaux. Il est négociable et peut être supprimé par l'AGE (rapport spécial du CAC) pour ouvrir le capital à des investisseurs." },
    { id: 'ue2-131', ue: 2, q: "Comment réduit-on le capital d'une société ?", a: "Par décision d'AGE, soit pour absorber des pertes (réduction motivée par les pertes, sans remboursement), soit par remboursement ou rachat et annulation de titres (réduction non motivée par des pertes, avec droit d'opposition des créanciers). Le capital ne peut descendre sous le minimum légal." },
    { id: 'ue2-132', ue: 2, q: "Qu'est-ce que la transformation d'une société ?", a: "Changement de forme juridique sans création d'une personne morale nouvelle (art. L210-6 C. com.), décidé dans les conditions du changement de statuts avec, selon le cas, un rapport du commissaire aux comptes sur la situation des capitaux propres. Certaines transformations exigent l'unanimité (augmentation des engagements des associés)." },
    { id: 'ue2-27', ue: 2, q: "Quels sont les effets d'une fusion ?", a: "Transmission universelle du patrimoine de la société absorbée à l'absorbante et dissolution sans liquidation de l'absorbée ; ses associés reçoivent des titres de l'absorbante (parité d'échange). La fusion est approuvée par les AGE et soumise à publicité et à l'opposition des créanciers." },
    { id: 'ue2-133', ue: 2, q: "Fusion, scission, apport partiel d'actif : quelles différences ?", a: "Fusion : une société absorbe une ou plusieurs autres (ou création d'une nouvelle). Scission : le patrimoine d'une société est réparti entre plusieurs sociétés existantes ou nouvelles. Apport partiel d'actif : une société apporte une branche d'activité (sans dissolution) à une autre." },
    { id: 'ue2-28', ue: 2, q: "Causes de dissolution d'une société ?", a: "Arrivée du terme, réalisation ou extinction de l'objet, annulation, dissolution anticipée décidée par les associés, décision de justice (justes motifs), réunion de toutes les parts en une seule main (SARL : régularisation possible dans un délai d'un an)." },
    { id: 'ue2-134', ue: 2, q: "Comment se déroule la liquidation d'une société ?", a: "La personnalité morale subsiste pour les besoins de la liquidation. Le liquidateur réalise l'actif, paie le passif et répartit le boni (solde) entre les associés. Clôture de la liquidation, puis radiation au RCS : la personnalité morale disparaît." },
    { id: 'ue2-135', ue: 2, q: "Qu'est-ce que la dissolution-confusion (TUP) ?", a: "Quand tous les titres sont réunis en une seule main (associé unique personne morale), celui-ci peut décider la dissolution sans liquidation : le patrimoine est transmis à l'associé unique (transmission universelle du patrimoine), après un délai d'opposition de 30 jours pour les créanciers." },

    // ---------- Responsabilités et contrôle ----------
    { id: 'ue2-25', ue: 2, q: "Abus de majorité, de minorité et d'égalité ?", a: "Abus de majorité : décision contraire à l'intérêt social prise dans le seul intérêt des majoritaires. Abus de minorité : blocage contraire à l'intérêt social dans le seul intérêt des minoritaires. Abus d'égalité : même chose entre deux groupes à 50/50." },
    { id: 'ue2-26', ue: 2, q: "Responsabilités des dirigeants ?", a: "Civile (faute de gestion, action sociale au nom de la société ou action individuelle d'un tiers ou d'un associé, prescrite par 3 ans), pénale (abus de biens sociaux, présentation de comptes inexacts) et en cas de procédure collective (responsabilité pour insuffisance d'actif, sanctions de faillite personnelle)." },
    { id: 'ue2-136', ue: 2, q: "Qui est dirigeant de droit et dirigeant de fait ?", a: "Dirigeant de droit : régulièrement désigné (gérant, président, administrateur...). Dirigeant de fait : personne qui exerce en toute indépendance une activité positive de direction sans mandat. Les responsabilités civile et pénale s'appliquent aux deux." },
    { id: 'ue2-30', ue: 2, q: "Différence entre pacte d'associés et statuts ?", a: "Les statuts sont publiés et opposables à tous. Le pacte d'associés est un contrat souvent confidentiel entre associés, qui n'engage qu'eux (préemption, sortie conjointe, non-concurrence, gouvernance...). Les clauses du pacte ne sont pas opposables à la société sauf si elle y est partie." },

    // ---------- Fonds de commerce ----------
    { id: 'ue2-137', ue: 2, q: "Qu'est-ce qu'un fonds de commerce et quels éléments le composent ?", a: "Ensemble de biens mobiliers corporels (matériel, marchandises) et incorporels (clientèle, achalandage, nom commercial, enseigne, droit au bail, marques, brevets, licences) affectés à une activité. La clientèle en est l'élément essentiel, sans lequel il n'y a pas de fonds." },
    { id: 'ue2-138', ue: 2, q: "Quelles mentions obligatoires doit contenir l'acte de vente d'un fonds de commerce ?", a: "L'origine de propriété, les privilèges et nantissements, le chiffre d'affaires et les résultats des trois derniers exercices, le bail (date, durée, loyer, identité du bailleur). À défaut, l'acquéreur peut demander la nullité dans l'année de la vente." },
    { id: 'ue2-139', ue: 2, q: "Quelle publicité et quelle protection des créanciers lors de la vente d'un fonds de commerce ?", a: "Publication dans un journal d'annonces légales et au BODACC. Les créanciers du vendeur disposent de 10 jours à compter de la publication au BODACC pour former opposition. Le prix est indisponible pendant ce délai (séquestre ou dépôt chez le notaire)." },
    { id: 'ue2-140', ue: 2, q: "Quelles garanties le vendeur d'un fonds de commerce doit-il à l'acquéreur ?", a: "Garantie d'éviction (ne pas concurrencer, clause de non-rétablissement limitée dans le temps et l'espace), garantie des vices cachés, délivrance du fonds et de ses éléments, et garantie du bail. L'acquéreur doit payer le prix et les droits d'enregistrement." },
    { id: 'ue2-141', ue: 2, q: "Quelle information des salariés lors de la cession d'un fonds de commerce ?", a: "Dans les entreprises de moins de 250 salariés, le propriétaire informe les salariés de son projet de cession pour qu'ils puissent présenter une offre. La loi de simplification de 2026 a réduit le délai d'information de 2 mois à 1 mois et la sanction de 2 % à 0,5 % du prix de cession.", d: "Loi n° 2026-403 du 26/05/2026 — à vérifier dans ton cours" },
    { id: 'ue2-142', ue: 2, q: "Qu'est-ce que la location-gérance ?", a: "Contrat par lequel le propriétaire d'un fonds en concède l'exploitation à un locataire-gérant, commerçant à ses risques et périls, moyennant une redevance. Elle doit être publiée ; le loueur est solidairement responsable des dettes du gérant pendant 6 mois après la publication." },
    { id: 'ue2-143', ue: 2, q: "Nantissement du fonds de commerce : régime ?", a: "Sûreté réelle sans dépossession : le débiteur garde l'exploitation. Il est constaté par écrit, inscrit au greffe (greffe du tribunal de commerce) dans les 30 jours ; l'inscription est valable 10 ans, renouvelable. Le créancier bénéficie d'un droit de préférence et d'un droit de suite." },
    { id: 'ue2-144', ue: 2, q: "Quels droits d'enregistrement frappent la cession d'un fonds de commerce ?", a: "Barème par tranche payé par l'acquéreur : 0 % jusqu'à 23 000 €, 3 % de 23 001 € à 200 000 €, 5 % au-delà de 200 000 €. Les parts de SARL/SNC : 3 % après abattement de 23 000 € (proratisé) ; les actions de SA/SAS : 0,1 %.", d: "Barèmes en vigueur en 2026 (à confirmer avec ton cours)" },
    { id: 'ue2-145', ue: 2, q: "Comment protège-t-on les éléments incorporels du fonds (marque, brevet) ?", a: "Marque : enregistrement à l'INPI, protection de 10 ans renouvelable indéfiniment. Brevet : 20 ans non renouvelables. Nom de domaine, droits d'auteur et dessins et modèles se protègent aussi ; l'action en contrefaçon sanctionne l'atteinte au titulaire." },

    // ---------- Bail commercial ----------
    { id: 'ue2-146', ue: 2, q: "Quelles sont les conditions du statut des baux commerciaux ?", a: "Un local ou un immeuble ; l'exploitation d'un fonds de commerce, artisanal ou industriel par le locataire ; l'immatriculation du locataire au RCS ou au répertoire des métiers. Le statut est d'ordre public et organise le droit au renouvellement et à l'indemnité d'éviction." },
    { id: 'ue2-147', ue: 2, q: "Durée et résiliation du bail commercial ?", a: "Durée minimale de 9 ans (bail 3-6-9). Le locataire peut résilier à l'expiration de chaque période triennale (congé par commissaire de justice 6 mois avant) ; le bailleur ne peut donner congé que dans des cas limités (refus de renouvellement, reprise, ...). Renonciation à la triennale possible dans certains cas." },
    { id: 'ue2-148', ue: 2, q: "Qu'est-ce que le bail dérogatoire (précaire) ?", a: "Bail commercial échappant au statut, d'une durée maximale de 3 ans (durée totale en cas de renouvellements successifs), pour tester une activité ou une implantation. Au-delà, le preneur bénéficie du statut s'il reste dans les lieux." },
    { id: 'ue2-149', ue: 2, q: "Comment renouveler un bail commercial ?", a: "Le locataire demande le renouvellement dans les 6 mois précédant l'expiration (ou à tout moment après), le bailleur répond dans les 3 mois ; ou le bailleur donne congé avec offre de renouvellement 6 mois avant l'échéance. Si le bailleur refuse sans motif grave et légitime, il doit une indemnité d'éviction." },
    { id: 'ue2-150', ue: 2, q: "Qu'est-ce que l'indemnité d'éviction ?", a: "Somme due au locataire dont le bail n'est pas renouvelé (hors motif grave et légitime). Elle compense la perte du fonds : valeur marchande du fonds ou perte du droit au bail, frais de remplacement et de déménagement. Le locataire peut se maintenir dans les lieux jusqu'au paiement." },
    { id: 'ue2-151', ue: 2, q: "Comment le loyer est-il fixé et révisé ?", a: "Loyer initial libre. Révision triennale ou clause d'indexation selon l'indice des loyers commerciaux (ILC) ou des activités tertiaires (ILAT). Au renouvellement, le loyer est en principe plafonné (variation de l'indice), sauf modification notable des éléments (déplafonnement) ; le plafonnement est une règle d'ordre public.", d: "Encadrement symétrique de l'ILC (clause « tunnel ») reconnu pour les baux conclus ou renouvelés depuis le 28/05/2026" },
    { id: 'ue2-152', ue: 2, q: "Que change la loi de simplification de mai 2026 pour les baux commerciaux ?", a: "Dépôt de garantie plafonné à 3 mois de loyer pour les baux conclus ou renouvelés ; droit pour le locataire de payer son loyer chaque mois ; clauses « tunnel » d'indexation reconnues ; définition précise du local commercial pour le droit de préférence (bureaux et entrepôts exclus).", d: "Loi n° 2026-403 du 26/05/2026, en vigueur depuis le 28/05/2026 — à vérifier dans ton cours" },
    { id: 'ue2-153', ue: 2, q: "Quel est le droit de préférence du locataire commercial ?", a: "Quand le bailleur veut vendre le local, le locataire commercial bénéficie d'un droit de préférence : le bailleur doit le lui notifier (prix et conditions) et le locataire dispose de 1 mois pour accepter. Une définition du local commercial a été introduite pour les ventes postérieures au 26/05/2026.", d: "Loi Pinel du 18/06/2014 ; définition légale depuis la loi n° 2026-403" },
    { id: 'ue2-154', ue: 2, q: "Cession du bail, sous-location, déspécialisation ?", a: "Cession du bail : libre avec le fonds sauf clause contraire, le cédant reste garant du cessionnaire (3 ans). Sous-location : interdite sauf accord du bailleur. Déspécialisation : adjonction d'activités connexes (simple) ou changement d'activité (plénière) avec autorisation ou procédure." },
    { id: 'ue2-155', ue: 2, q: "Prescription des actions relatives au bail commercial ?", a: "Les actions exercées en vertu du statut des baux commerciaux se prescrivent par 2 ans (prescription biennale) à compter de l'événement qui y donne naissance (ex. congé, demande de renouvellement)." },

    // ---------- Financement ----------
    { id: 'ue2-156', ue: 2, q: "Quelles sont les principales sources de financement juridiquement accessibles à une société ?", a: "Fonds propres (apports, augmentation de capital, entrée d'investisseurs), emprunt bancaire, emprunt obligataire (SA, SAS), comptes courants d'associés, crédit-bail, affacturage, escompte, subventions, financement participatif (crowdfunding)." },
    { id: 'ue2-157', ue: 2, q: "Qu'est-ce que le cautionnement ?", a: "Contrat par lequel une personne (la caution) s'engage envers le créancier à payer la dette du débiteur principal si celui-ci est défaillant. Il est accessoire à la dette principale, doit être exprès et, pour les cautions personnes physiques, formalisé par une mention manuscrite ; le créancier professionnel doit respecter la proportionnalité de l'engagement." },
    { id: 'ue2-158', ue: 2, q: "Garantie autonome et lettre d'intention ?", a: "Garantie autonome : le garant s'engage à payer à première demande, indépendamment de la dette garantie (non accessoire). Lettre d'intention : engagement de faire ou de ne pas faire pour soutenir le débiteur, sans obligation de payer sa dette." },
    { id: 'ue2-159', ue: 2, q: "Quelles sont les principales sûretés réelles ?", a: "Gage (meubles, avec ou sans dépossession), nantissement (fonds de commerce, parts sociales, comptes de titres), hypothèque (immeubles), privilèges. Elles confèrent un droit de préférence et un droit de suite sur le bien affecté.", d: "Réforme du droit des sûretés : ordonnance n° 2021-1192 du 15/09/2021 (en vigueur depuis le 01/01/2022)" },
    { id: 'ue2-160', ue: 2, q: "Crédit-bail, affacturage, escompte : de quoi s'agit-il ?", a: "Crédit-bail : location de biens avec promesse de vente (levée d'option). Affacturage : cession de créances clients à un factor qui les encaisse et finance. Escompte : la banque avance le montant d'effets de commerce avant l'échéance, moyennant des agios." },
    { id: 'ue2-161', ue: 2, q: "Comptes courants d'associés : quel régime juridique ?", a: "Prêts de l'associé à la société : convention de compte courant avec taux d'intérêt (déductibles dans la limite fiscale) ; en SARL et SA, conventions réglementées ou interdites selon le cas. Ils constituent un financement souple, mais sont des dettes exigibles." },
    { id: 'ue2-162', ue: 2, q: "Emprunt obligataire : qui peut émettre et quelles règles ?", a: "Les sociétés par actions (SA, SAS) peuvent émettre des obligations, titres de créance qui confèrent à leur porteur un droit de créance (intérêts et remboursement). Les obligataires forment une masse représentée par un mandataire. L'émission est décidée par le conseil ou le dirigeant sur délégation de l'AG ; pour une SARL, l'émission est très encadrée." },
    { id: 'ue2-163', ue: 2, q: "Le financement participatif (crowdfunding) : comment est-il encadré ?", a: "Don, prêt ou investissement en capital via une plateforme agréée. Les prestataires de services de financement participatif sont régulés au niveau européen (règlement (UE) 2020/1503) ; les opérations en capital sont soumises à des plafonds d'offre (en euros) et à l'information des investisseurs.", d: "Règlement (UE) 2020/1503, applicable depuis 2021" },

    // ---------- Droit pénal des affaires ----------
    { id: 'ue2-164', ue: 2, q: "Classification des infractions et prescription de l'action publique ?", a: "Contraventions, délits, crimes. Prescription de l'action publique : 1 an pour les contraventions, 6 ans pour les délits, 20 ans pour les crimes. Pour les infractions occultes ou dissimulées (ex. ABS), le délai court à partir du jour où l'infraction est apparue, avec un délai butoir de 12 ans pour les délits.", d: "Loi n° 2017-242 du 27/02/2017" },
    { id: 'ue2-165', ue: 2, q: "Quels sont les éléments constitutifs d'une infraction ?", a: "Élément légal (texte d'incrimination), élément matériel (comportement ou résultat, tentative punissable pour les crimes et délits prévus) et élément moral (intention, sauf infractions non intentionnelles)." },
    { id: 'ue2-166', ue: 2, q: "Quelle est la responsabilité pénale des personnes morales ?", a: "Les personnes morales (sauf l'État) sont responsables pénalement des infractions commises pour leur compte par leurs organes ou représentants (art. 121-2 C. pén.). Amende égale au quintuple de celle prévue pour les personnes physiques, plus peines complémentaires (dissolution, interdictions...). Cela n'exclut pas la responsabilité des dirigeants." },
    { id: 'ue2-167', ue: 2, q: "Qu'est-ce que l'abus de biens sociaux (ABS) ?", a: "Fait pour un dirigeant (SARL, SA, SAS) de faire, de mauvaise foi, un usage des biens, du crédit, des pouvoirs ou des voix de la société qu'il sait contraire à l'intérêt de celle-ci, à des fins personnelles ou pour favoriser une autre société ou entreprise dans laquelle il est intéressé. Peine : 5 ans de prison et 375 000 € d'amende.", d: "Art. L241-3 et L242-6 C. com." },
    { id: 'ue2-168', ue: 2, q: "Quelles sont les infractions liées aux comptes et aux dividendes ?", a: "Présentation ou publication de comptes annuels inexacts (ne donnant pas une image fidèle) pour dissimuler la véritable situation, et distribution de dividendes fictifs : 5 ans d'emprisonnement et 375 000 € d'amende. Le commissaire aux comptes qui ne révèle pas les faits délictueux au procureur est aussi sanctionné." },
    { id: 'ue2-169', ue: 2, q: "Abus de confiance et escroquerie : définitions et peines ?", a: "Abus de confiance : détournement d'un bien remis à charge de le rendre ou de l'utiliser d'une manière déterminée (5 ans, 375 000 €). Escroquerie : tromper une personne par manœuvres frauduleuses pour obtenir un bien ou un service (5 ans, 375 000 €).", d: "Peines à confirmer avec ton cours" },
    { id: 'ue2-170', ue: 2, q: "Banqueroute : conditions et peines ?", a: "Délit commis par un commerçant, artisan ou dirigeant en cessation des paiements qui a dissimulé ou détourné de l'actif, augmenté frauduleusement le passif, tenu une comptabilité fictive ou omis de la tenir... Peine : 5 ans d'emprisonnement et 75 000 € d'amende (art. L654-3 C. com.)." },
    { id: 'ue2-171', ue: 2, q: "Faux, usage de faux et recel : de quoi s'agit-il ?", a: "Faux : altération frauduleuse de la vérité dans un écrit pouvant causer un préjudice (3 ans, 45 000 €). Recel : détenir ou transmettre un bien provenant d'un crime ou d'un délit (5 ans, 375 000 €)." },
    { id: 'ue2-172', ue: 2, q: "Blanchiment de capitaux : définition et obligations de vigilance ?", a: "Faciliter la justification mensongère de l'origine de biens ou revenus provenant d'un crime ou délit, ou concourir à un placement ou une conversion de ces produits (5 ans, 375 000 €). Les professionnels (experts-comptables, banques, avocats...) doivent identifier leurs clients et déclarer les soupçons à Tracfin." },
    { id: 'ue2-173', ue: 2, q: "Corruption et trafic d'influence ?", a: "Corruption : le fait de proposer ou d'accepter un avantage indu en échange d'un acte ou d'une abstention. Corruption publique active : 10 ans et 1 M€ ; corruption privée : 5 ans et 500 000 €. Le trafic d'influence sanctionne l'avantage obtenu en abusant de son influence réelle ou supposée.", d: "Peines à confirmer avec ton cours" },
    { id: 'ue2-174', ue: 2, q: "Délit d'initié et manipulation de cours ?", a: "Délit d'initié : utiliser une information privilégiée pour acheter ou vendre des instruments financiers ou la communiquer indûment. Sanctions pénales : 5 ans et 100 M€ (ou jusqu'au décuple du profit). Autorité compétente : AMF (sanctions administratives) et tribunal correctionnel." },
    { id: 'ue2-175', ue: 2, q: "Loi Sapin II : dispositifs anticorruption et lanceurs d'alerte ?", a: "Loi n° 2016-1691 du 9 décembre 2016 : création de l'Agence française anticorruption (AFA), programme de conformité anticorruption obligatoire pour les grandes entreprises (au moins 500 salariés et 100 M€ de chiffre d'affaires), protection des lanceurs d'alerte, convention judiciaire d'intérêt public (CJIP) pour les personnes morales.", d: "Loi Waserman n° 2022-401 du 21/03/2022 renforçant la protection des lanceurs d'alerte" },
    { id: 'ue2-176', ue: 2, q: "Fraude fiscale : quelles peines pénales ?", a: "Fraude fiscale (art. 1741 CGI) : 5 ans d'emprisonnement et 500 000 € d'amende (portés à 7 ans et 3 M€ en bande organisée ou avec manœuvres aggravées). Les poursuites sont engagées sur plainte de l'administration après avis conforme de la Commission des infractions fiscales.", d: "Peines à confirmer avec ton cours" },
    { id: 'ue2-177', ue: 2, q: "Délégation de pouvoirs : quel effet pour la responsabilité pénale du dirigeant ?", a: "Le chef d'entreprise peut s'exonérer de sa responsabilité pénale en déléguant ses pouvoirs à un préposé pourvu de la compétence, de l'autorité et des moyens nécessaires, avec une délégation précise et non équivoque. Il reste responsable s'il a participé à l'infraction." },
    { id: 'ue2-178', ue: 2, q: "Peines complémentaires encourues par les dirigeants ?", a: "Interdiction de diriger ou de gérer (jusqu'à 15 ans), interdiction des droits civiques, publication de la condamnation, confiscation. Les juridictions commerciales peuvent prononcer faillite personnelle ou interdiction de gérer en cas de procédure collective." }
  );

  Q.push(
    { id: 'q-ue2-01', ue: 2, q: "Quel est le capital minimum d'une SA ?", choices: ["1 €", "8 000 €", "37 000 €", "100 000 €"], answer: 2, expl: "Le capital minimum d'une société anonyme est de 37 000 €." },
    { id: 'q-ue2-02', ue: 2, q: "Dans une SARL, la responsabilité des associés est…", choices: ["Illimitée et solidaire", "Limitée aux apports", "Illimitée mais non solidaire", "Limitée au double des apports"], answer: 1, expl: "Les associés de SARL ne supportent les pertes qu'à concurrence de leurs apports." },
    { id: 'q-ue2-03', ue: 2, q: "Quelle majorité faut-il pour modifier les statuts d'une SARL ?", choices: ["Plus de la moitié des parts", "2/3 des voix exprimées", "3/4 des parts sociales", "L'unanimité"], answer: 2, expl: "Les décisions extraordinaires en SARL exigent les 3/4 des parts sociales." },
    { id: 'q-ue2-04', ue: 2, q: "En SA, quelle est la majorité requise en AGE ?", choices: ["Majorité simple des voix exprimées", "2/3 des voix exprimées", "3/4 du capital", "L'unanimité"], answer: 1, expl: "L'assemblée générale extraordinaire statue à la majorité des 2/3 des voix exprimées (abstentions, blancs et nuls exclus).", d: "Art. L225-96 C. com." },
    { id: 'q-ue2-05', ue: 2, q: "Capital 100 000 €, réserve légale 8 000 €, bénéfice 60 000 €. Quelle dotation à la réserve légale ?", choices: ["3 000 €", "2 000 €", "5 000 €", "6 000 €"], answer: 1, expl: "5 % de 60 000 = 3 000, mais la réserve est plafonnée à 10 % du capital = 10 000 : il ne manque que 2 000 €." },
    { id: 'q-ue2-06', ue: 2, q: "Quelle société impose à ses associés commerçants une responsabilité indéfinie et solidaire ?", choices: ["SARL", "SAS", "SNC", "SA"], answer: 2, expl: "Dans une société en nom collectif, les associés sont commerçants et répondent indéfiniment et solidairement des dettes." },
    { id: 'q-ue2-07', ue: 2, q: "Les capitaux propres tombent à moins de la moitié du capital. Dans quel délai consulte-t-on les associés ?", choices: ["1 mois", "4 mois après l'approbation des comptes", "6 mois après la clôture", "2 ans"], answer: 1, expl: "Les associés doivent décider dans les 4 mois qui suivent l'approbation des comptes de la dissolution anticipée éventuelle." },
    { id: 'q-ue2-08', ue: 2, q: "Dans une SAS, quel organe est légalement obligatoire ?", choices: ["Un conseil d'administration", "Un président", "Un directoire", "Un conseil de surveillance"], answer: 1, expl: "La SAS doit désigner un président ; le reste de l'organisation relève de la liberté statutaire." },
    { id: 'q-ue2-09', ue: 2, q: "À partir de quand une société a-t-elle la personnalité morale ?", choices: ["Signature des statuts", "Dépôt du capital", "Immatriculation au RCS", "Première facture"], answer: 2, expl: "La personnalité morale s'acquiert à l'immatriculation au registre du commerce et des sociétés." },
    { id: 'q-ue2-10', ue: 2, q: "Quel est le nombre maximum d'associés d'une SARL ?", choices: ["50", "100", "150", "Illimité"], answer: 1, expl: "Une SARL compte de 1 à 100 associés." },
    { id: 'q-ue2-11', ue: 2, q: "Un apport en nature en SARL nécessite un commissaire aux apports si sa valeur dépasse…", choices: ["5 000 €", "10 000 €", "30 000 €", "100 000 €"], answer: 2, expl: "Au-delà de 30 000 € (ou si les apports en nature dépassent la moitié du capital), un commissaire aux apports est requis sauf décision unanime des associés." },
    { id: 'q-ue2-12', ue: 2, q: "Quel est l'effet d'une fusion-absorption sur la société absorbée ?", choices: ["Liquidation puis partage", "Dissolution sans liquidation", "Changement de forme", "Aucun effet"], answer: 1, expl: "Son patrimoine est transmis en bloc à l'absorbante et elle est dissoute sans liquidation." },
    { id: 'q-ue2-101', ue: 2, q: "Quel est le quorum de l'AGO d'une SA à la 1re convocation ?", choices: ["Aucun", "1/5 des actions ayant le droit de vote", "1/4 des actions", "La moitié des actions"], answer: 1, expl: "L'AGO ne délibère valablement sur 1re convocation que si les actionnaires présents ou représentés possèdent au moins 1/5 des actions ayant le droit de vote ; aucun quorum à la 2e convocation.", d: "Art. L225-98 C. com." },
    { id: 'q-ue2-102', ue: 2, q: "Quel est le quorum de l'AGE d'une SA à la 1re convocation ?", choices: ["1/5 des actions", "1/4 des actions", "1/3 des actions", "La moitié des actions"], answer: 1, expl: "AGE : 1/4 des actions ayant le droit de vote sur 1re convocation, 1/5 sur 2e convocation.", d: "Art. L225-96 C. com." },
    { id: 'q-ue2-103', ue: 2, q: "Une société dépasse 6 M€ de bilan, 11 M€ de CA HT et compte 20 salariés sur deux exercices. Doit-elle nommer un commissaire aux comptes (SARL) ?", choices: ["Non : un seul seuil est dépassé", "Oui : deux seuils sur trois sont dépassés", "Non : seuls les 50 salariés comptent", "Oui : un seul seuil suffit"], answer: 1, expl: "Seuils : 5 M€ de bilan, 10 M€ de CA, 50 salariés. Deux sur trois (bilan et CA) sont dépassés sur 2 exercices consécutifs : la nomination est obligatoire.", d: "Seuils en vigueur depuis le 01/01/2024 (décret n° 2024-152)" },
    { id: 'q-ue2-104', ue: 2, q: "Quel est le montant maximal de la durée d'une société selon le Code civil ?", choices: ["50 ans", "99 ans", "150 ans", "Illimitée"], answer: 1, expl: "La durée de la société ne peut excéder 99 ans (renouvelable)." },
    { id: 'q-ue2-105', ue: 2, q: "Que produit une clause léonine ?", choices: ["La nullité de la société", "Elle est réputée non écrite", "La dissolution de la société", "Rien, elle est valable"], answer: 1, expl: "La clause léonine est réputée non écrite ; la société reste valable." },
    { id: 'q-ue2-106', ue: 2, q: "Qui répond des actes passés pour une société en formation ?", choices: ["La société, qui a déjà la personnalité morale", "Les personnes qui ont agi, solidairement", "L'État", "Les futurs associés non signataires"], answer: 1, expl: "Avant l'immatriculation, ceux qui ont agi en répondent solidairement jusqu'à la reprise par la société." },
    { id: 'q-ue2-107', ue: 2, q: "Quelle est la durée d'un mandat de commissaire aux comptes ?", choices: ["3 exercices", "4 exercices", "6 exercices", "9 exercices"], answer: 2, expl: "Le mandat est de 6 exercices (pour les entités qui doivent légalement nommer un CAC)." },
    { id: 'q-ue2-108', ue: 2, q: "Combien de membres compte le conseil d'administration d'une SA ?", choices: ["De 1 à 5", "De 2 à 10", "De 3 à 18", "De 5 à 24"], answer: 2, expl: "Le conseil d'administration compte 3 à 18 membres (le conseil de surveillance aussi)." },
    { id: 'q-ue2-109', ue: 2, q: "Quelle est la durée de la période d'opposition des créanciers lors de la vente d'un fonds de commerce ?", choices: ["10 jours après la publication au BODACC", "1 mois après la signature", "3 mois", "Aucune opposition n'est possible"], answer: 0, expl: "Les créanciers du vendeur ont 10 jours à compter de la publication au BODACC pour former opposition sur le prix." },
    { id: 'q-ue2-110', ue: 2, q: "Quelle est la durée minimale d'un bail commercial ?", choices: ["3 ans", "6 ans", "9 ans", "12 ans"], answer: 2, expl: "Bail de 9 ans minimum, avec faculté de résiliation triennale pour le locataire." },
    { id: 'q-ue2-111', ue: 2, q: "Que doit payer le bailleur qui refuse sans motif grave le renouvellement du bail commercial ?", choices: ["Une indemnité d'occupation", "Une indemnité d'éviction", "Des dommages-intérêts forfaitaires de 1 an de loyer", "Rien"], answer: 1, expl: "Le refus de renouvellement sans motif grave et légitime ouvre droit à l'indemnité d'éviction." },
    { id: 'q-ue2-112', ue: 2, q: "Quel plafond de dépôt de garantie la loi de simplification de 2026 prévoit-elle pour les baux commerciaux conclus ou renouvelés ?", choices: ["1 mois de loyer", "3 mois de loyer", "6 mois de loyer", "12 mois de loyer"], answer: 1, expl: "Le dépôt de garantie (et l'ensemble des garanties) ne peut dépasser 3 mois de loyer, soit un trimestre.", d: "Loi n° 2026-403 du 26/05/2026 — à vérifier dans ton cours" },
    { id: 'q-ue2-113', ue: 2, q: "Quel est le délai de prescription de l'action publique pour un délit ?", choices: ["1 an", "3 ans", "6 ans", "20 ans"], answer: 2, expl: "6 ans pour les délits, 1 an pour les contraventions, 20 ans pour les crimes (loi du 27 février 2017)." },
    { id: 'q-ue2-114', ue: 2, q: "Peine maximale encourue pour abus de biens sociaux ?", choices: ["2 ans et 30 000 €", "3 ans et 75 000 €", "5 ans et 375 000 €", "10 ans et 1 M€"], answer: 2, expl: "5 ans d'emprisonnement et 375 000 € d'amende (art. L241-3 et L242-6 C. com.).", d: "Peines à confirmer avec ton cours" },
    { id: 'q-ue2-115', ue: 2, q: "Une personne morale est-elle pénalement responsable ?", choices: ["Jamais", "Oui, des infractions commises pour son compte par ses organes ou représentants", "Seulement pour les contraventions", "Seulement l'État"], answer: 1, expl: "Art. 121-2 C. pén. : responsabilité pénale des personnes morales (sauf l'État), sans exclure celle des personnes physiques." },
    { id: 'q-ue2-116', ue: 2, q: "Quel est le montant maximum de l'amende pour une personne morale par rapport à celle d'une personne physique ?", choices: ["Le même", "Le double", "Le quintuple", "Le décuple"], answer: 2, expl: "L'amende est égale au quintuple de celle prévue pour les personnes physiques (art. 131-38 C. pén.)." },
    { id: 'q-ue2-117', ue: 2, q: "Un dirigeant peut-il s'exonérer de sa responsabilité pénale ?", choices: ["Non, jamais", "Oui, par une délégation de pouvoirs valable à un préposé compétent doté de l'autorité et des moyens", "Oui, en démissionnant avant l'infraction uniquement", "Oui, en payant l'amende"], answer: 1, expl: "La délégation de pouvoirs est une cause d'exonération si le délégataire a compétence, autorité et moyens, et si le dirigeant n'a pas participé aux faits." },
    { id: 'q-ue2-118', ue: 2, q: "Quel est le taux des droits d'enregistrement sur la cession d'actions de SA ou de SAS ?", choices: ["0,1 %", "1 %", "3 %", "5 %"], answer: 0, expl: "0,1 % sans plafond (3 % après abattement pour les parts de SARL, 0/3/5 % par tranches pour un fonds de commerce).", d: "Barèmes 2026 — à confirmer avec ton cours" },
    { id: 'q-ue2-119', ue: 2, q: "Quel est le délai de prescription de l'action en nullité d'une société ?", choices: ["1 an", "3 ans", "5 ans", "10 ans"], answer: 1, expl: "L'action en nullité d'une société se prescrit par 3 ans à compter du jour où la nullité est encourue." },
    { id: 'q-ue2-120', ue: 2, q: "Les statuts d'une SAS peuvent-ils prévoir une clause d'inaliénabilité ?", choices: ["Non, jamais", "Oui, pour une durée limitée (10 ans maximum)", "Oui, sans limite de durée", "Oui, mais seulement 1 an"], answer: 1, expl: "La clause d'inaliénabilité en SAS est possible pour une durée ne pouvant excéder 10 ans." },
    { id: 'q-ue2-121', ue: 2, q: "Quelle forme d'entreprise individuelle sépare automatiquement patrimoine professionnel et personnel depuis 2022 ?", choices: ["L'EIRL uniquement", "Tout entrepreneur individuel (statut unique)", "L'auto-entrepreneur seulement", "La SNC"], answer: 1, expl: "Depuis la loi du 14 février 2022, tout EI bénéficie de la séparation des patrimoines professionnel et personnel.", d: "Applicable depuis le 15/05/2022" }
  );
})();
